from pathlib import Path
import re
path = Path('xarray/core/dataarray.py')
text = path.read_text()
old = """        # pull variables out of datarray\n        data_dict = {}\n        for k in variables:\n            data_dict[k] = self.sel({variable_dim: k}).squeeze(drop=True)\n\n        # unstacked dataset\n        return Dataset(data_dict)\n"""
if old not in text:
    raise SystemExit('Expected block not found')
new = """        # pull variables out of datarray
        data_dict = {}
        for k in variables:
            var = self.sel({variable_dim: k})

            # If `dim` is still present after selecting the variable level, we
            # need to unstack it to restore the original dimensions.
            if dim in var.dims:
                stacked_index = var.indexes.get(dim)
                if isinstance(stacked_index, pd.MultiIndex):
                    var = var.unstack(dim)

            var = var.squeeze(drop=True)

            # Selecting a single label from the stacked dimension can leave a
            # scalar coordinate with the same name as `dim` (e.g. when stacking
            # only over the variable level). This coordinate differs across the
            # variables and would raise a MergeError when constructing the
            # output Dataset.
            if dim in var.coords and dim not in var.dims:
                var = var.reset_coords(dim, drop=True)

            data_dict[k] = var

        # unstacked dataset
        return Dataset(data_dict)
"""
path.write_text(text.replace(old, new))
print('patched', path)
