arr_b = xr.DataArray(np.arange(x*y).reshape(x,y), dims=('x','y'), coords={'y':np.arange(y)})
D = xr.Dataset({'a':arr_a, 'b':arr_b})
stacked2 = D.to_stacked_array('features', sample_dims=['x'])
print('stacked2', stacked2)
idx = stacked2.indexes['features']
print('levels', idx.names)
for k in idx.levels[0]:
    var = stacked2.sel({'variable': k})
    print('\nraw sel', k, var.dims, list(var.coords))
    if 'features' in var.dims and isinstance(var.indexes.get('features'), type(idx)):
        var = var.unstack('features')
    var = var.squeeze(drop=True)
    if 'features' in var.coords and 'features' not in var.dims:
        var = var.reset_coords('features', drop=True)
    print('processed', k)
    print(var)
    print('dims', var.dims)
    print('coords', {c:(var.coords[c].dims, var.coords[c].values) for c in var.coords})

# attempt to construct dataset explicitly
